// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part models only the nut, not the aluminium extrusion it fits into.
// It is a generic T-nut and may need to be adapted (e.g. wider flange, different
// neck size, screw-hole diameter) to match a specific extrusion profile.
//
// Author: generic design
// License: public domain

$fn = 48;

// ---- Dimensions (mm) ----
flange_w   = 12;   // flange width (Y)
flange_t   = 2;    // flange thickness (z = 0 to 2)
neck_w     = 7;    // neck width (Y), centred on flange
neck_h     = 4;    // neck height above flange (z = 2 to 6)
screw_d    = 3.4;  // through-hole diameter for the screw
eps        = 0.5;  // cutter overshoot past faces

// Derived
total_h = flange_t + neck_h;  // 6 mm overall height

difference() {
    union() {
        // Bottom flange: y = -flange_w/2 .. +flange_w/2, z = 0 .. flange_t
        translate([-flange_w/2, -flange_w/2, 0])
            cube([flange_w, flange_w, flange_t]);

        // Neck: y = -neck_w/2 .. +neck_w/2, z = flange_t .. total_h
        translate([-neck_w/2, -neck_w/2, flange_t])
            cube([neck_w, neck_w, neck_h]);
    }

    // Central screw hole, through the full height
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = total_h + 2*eps);
}
