```openscad
// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up (+Z).
//
// NOTE: This part models only the nut that goes into the T-slot. It does not
// model the aluminium extrusion itself. For a complete printed profile see the
// related "aluminium_extrusion" part.
//
// Author: scocioba (simplified for FDM printing - no overhangs/bridges)
// License: CC0 1.0 (public domain)
//
// TODO: add a small channel or groove on the top of the flange to keep the nut
// from sliding out of the slot under load.

// ---------------- Parameters ----------------
slot_width   = 10;    // width of the extrusion slot (Y)
flange_thick = 2.5;   // thickness of the bottom flange (Z)
neck_width   = 6;     // width of the centred neck above the flange (Y)
neck_height  = 6.5;   // height the neck rises above the flange top (Z)
screw_d      = 3.4;   // diameter of the central screw hole
eps          = 0.5;   // cutter overshoot past faces

$fn = 64;

// Derived
flange_h = flange_thick;              // z = 0 .. 2.5
neck_top = flange_h + neck_height;    // z = 2.5 .. 9.0
y1       = -slot_width / 2;
y2       = slot_width / 2;

// ---------------- Model ----------------
difference() {
    union() {
        // Bottom flange: full width, centred on origin in X and Y
        translate([y1, y1, 0])
            cube([slot_width, slot_width, flange_h]);

        // Neck: centred on origin in X and Y, sits on the flange
        translate([y1 - (slot_width - neck_width) / 2,
                   y1 - (slot_width - neck_width) / 2,
                   flange_h])
            cube([neck_width, neck_width, neck_height]);
    }

    // Central screw hole, through the whole part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = neck_top + 2 * eps);
}
