```openscad
// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Units: mm. Print orientation: plate flat on bed, ribs pointing up (+Z).

// ---------------- Parameters ----------------
plate_len   = 120;   // plate length along X
plate_wid   = 80;    // plate width along Y
plate_thk   = 3;     // plate thickness (z = 0 to 3)

rib_thk     = 3;     // rib thickness along X
rib_h       = 5;     // rib height above plate (z = 3 to 8)
rib_count   = 3;     // number of ribs
rib_pitch   = 30;    // centre-to-centre spacing of ribs along X
outer_dist  = 30;    // distance from outer rib centre to plate end

eps         = 0.5;   // cutter overshoot past faces
$fn         = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
plate_z0 = 0;
plate_z1 = plate_thk;
rib_z0   = plate_z1;   // ribs start at top of plate
rib_z1   = rib_z0 + rib_h;

// Check: rib_count * pitch + 2 * outer_dist = 3*30 + 2*30 = 120 mm
assert(abs(rib_count * rib_pitch + 2 * outer_dist - plate_len) < 0.001,
       "Rib layout does not span the plate length.");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, centred on the plate
    for (i = [0 : rib_count - 1]) {
        x_c = i * rib_pitch - (rib_count - 1) * rib_pitch / 2;
        translate([x_c - rib_thk/2, -plate_wid/2, rib_z0])
            cube([rib_thk, plate_wid, rib_h]);
    }
}
