// Stiffened cover panel - flat plate with 4 longitudinal ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 80;    // plate length along X (mm)
plate_wid   = 80;    // plate width along Y (mm)
plate_thk   = 2;     // plate thickness along Z (mm)

rib_thk     = 2;     // rib thickness along X (mm)
rib_h       = 5;     // rib height above plate top (mm)
              // -> rib top at z = plate_thk + rib_h = 7

rib_count   = 4;     // number of ribs
rib_pitch   = 16;    // centre-to-centre spacing of ribs (mm)
outer_dist  = 16;    // distance from outer rib centre to plate end (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 64;    // curve resolution

// ---------------- Derived ----------------
plate_z0 = 0;                        // plate bottom
plate_z1 = plate_thk;                // plate top
rib_z0   = plate_z1;                 // rib bottom
rib_z1   = rib_z0 + rib_h;           // rib top
x_start  = -plate_len/2 + outer_dist; // first rib centre X
// check: last rib centre X = x_start + (rib_count-1)*rib_pitch
//       = -40 + 16 + 3*16 = 16 -> 16 mm from right end (80 - 16 = 64)

// ---------------- Model ----------------
union() {
    // Base plate
    translate([0, 0, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([x_start + i * rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   rib_z0])
            cube([rib_thk, plate_wid, rib_h + eps]); // extend past top face
    }
}
