// Powder measuring scoop - hollow spherical bowl with flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
bowl_r      = 12;    // outer radius of spherical bowl
wall        = 2;     // wall thickness of bowl
bowl_z0     = 12;    // z of sphere centre (lower half kept, rim at z = 12)
handle_w    = 12;    // handle width (Y)
handle_t    = 3;     // handle thickness (Z)
handle_x0   = 10;    // handle start (X)
handle_x1   = 92;    // handle end (X)
eps         = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    union() {
        // Bowl: lower half of hollow sphere
        translate([0, 0, bowl_z0])
            sphere(r = bowl_r, $fn = 192);
        translate([0, 0, bowl_z0 - wall])
            sphere(r = bowl_r - wall, $fn = 192);

        // Handle: flat plate, top face flush with rim (z = 9 to 12)
        translate([handle_x0, -handle_w / 2, bowl_z0 - wall - eps])
            cube([handle_x1 - handle_x0, handle_w, handle_t + 2 * eps]);
    }

    // Support block under the bowl so it sits on z = 0
    translate([0, 0, bowl_z0 - wall - 0.01])
        cube([100, 100, wall + 0.01]);
}
