// Powder measuring scoop - hollow spherical bowl with flat handle
// Units: mm. Print orientation: bowl bottom on bed (z = 0), handle along +X.

// ---------- Parameters ----------
bowl_outer_radius   = 12;   // outer radius of spherical bowl
bowl_wall_thickness = 2;    // thickness of bowl wall
bowl_centre         = [0, 0, 12]; // sphere centre (lower half kept)
handle_width        = 8;    // handle width (Y)
handle_thickness    = 4;    // handle thickness (Z)
handle_x_start      = 10;   // handle start (X)
handle_x_end        = 112;  // handle end (X)
cut_extra           = 0.5;  // overshoot for clean boolean cuts

$fn = 96;

// ---------- Derived ----------
bowl_inner_radius = bowl_outer_radius - bowl_wall_thickness;
handle_top_z      = bowl_centre[2] - bowl_wall_thickness; // flush with rim (z = 8)

// ---------- Model ----------
union() {
    // Hollow spherical bowl (lower half)
    difference() {
        sphere(r = bowl_outer_radius, center = bowl_centre);
        translate([0, 0, -cut_extra])
            sphere(r = bowl_inner_radius, center = bowl_centre);
        // keep only lower half: cut away z > bowl_centre[2]
        translate([0, 0, bowl_centre[2]])
            cube([bowl_outer_radius * 2, bowl_outer_radius * 2, cut_extra]);
    }

    // Flat handle, top face flush with rim
    translate([handle_x_start, -handle_width / 2, handle_top_z])
        cube([handle_x_end - handle_x_start, handle_width, handle_thickness]);
}
