            cylinder(r = bowl_r, h = bowl_z + 0.01, $fn = 96);   // outer
        translate([0, 0, bowl_z + wall])
            cylinder(r = bowl_r - wall, h = bowl_z - wall + 0.01, $fn = 96); // inner

