// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 96;

// ---- Plate ----
plate_len   = 50;    // plate length along X
plate_wid   = 25;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;     // knuckle diameter
knuckle_z   = 3.5;   // knuckle axis height (Z)
knuckle_y   = 12.5;  // knuckle axis Y position
knuckle_n     = 5;   // number of segments
knuckle_pitch = plate_len / knuckle_n; // 10 mm segment length
knuckle_ids   = [1, 3, 5]; // segments with knuckles

// ---- Pin ----
pin_d       = 3;     // pin hole diameter

// ---- Misc ----
eps         = 0.5;   // cutter overshoot past faces

difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X axis
        for (id = knuckle_ids)
            translate([-knuckle_pitch*knuckle_n/2 + id*knuckle_pitch,
                       knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_len + 2*eps, $fn = 96);
    }

    // Pin holes through every knuckle
    for (id = knuckle_ids)
        translate([-knuckle_pitch*knuckle_n/2 + id*knuckle_pitch,
                   knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_len + 2*eps, $fn = 64);
}
