```openscad
// Tapered riser block for beaker setting
// Print orientation: base on bed (z = 0), top face at z = 30

// ---------- Parameters ----------
base_size   = 80;   // bottom square side (X and Y)
top_size    = 50;   // top square side (X and Y)
height      = 30;   // block height (z = 0 to z = 30)
pocket_size = 40;   // square pocket side (X and Y)
pocket_depth = 5;   // square pocket depth from top face
eps         = 0.5;  // overshoot for clean boolean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Frustum body: hull of bottom and top squares, centred in X/Y
    hull() {
        translate([-base_size/2, -base_size/2, 0])
            cube([base_size, base_size, height]);
        translate([-top_size/2, -top_size/2, height])
            cube([top_size, top_size, height]);
    }

