// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 15;    // grip section width (Y)
grip_length    = 30;    // grip section length (X)
transition_len = 10;    // transition section length (X)
cut_extra      = 0.5;   // cutter overshoot past end faces

$fn = 64;

// ---------- Derived ----------
w_tight   = gauge_width;
w_grip    = grip_width;
x0        = -total_length / 2;  // left end X
x1        = x0 + grip_length;   // grip end / transition start
x2        = x1 + transition_len; // transition end / gauge start
x3        = x2 + gauge_length;   // gauge end / transition start
x4        = x3 + transition_len; // transition end / grip start
x5        = x4 + grip_length;   // right end X

// ---------- Model ----------
difference() {
    // Outer shape: grip - transition - gauge - transition - grip
    union() {
        for (i = [0 : 4]) {
            translate([x0 + i * grip_length, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);
        }
        translate([x1, -w_grip / 2, 0])
            linear_extrude(thickness)
                polygon([[-transition_len / 2, 0],
                         [transition_len / 2, 0],
                         [transition_len / 2, w_grip - w_tight],
                         [-transition_len / 2, w_grip - w_tight]]);
        translate([x2, -w_grip / 2, 0])
            linear_extrude(thickness)
                polygon([[-(x3 - x2), 0],
                         [(x3 - x2), 0],
                         [(x3 - x2), w_grip - w_tight],
                         [-(x3 - x2), w_grip - w_tight]]);
    }

    // Central cutout: rectangle along X, centred on origin
    translate([x0 + gauge_length / 2 - cut_extra,
               -w_tight / 2,
               -cut_extra])
        cube([gauge_length + 2 * cut_extra,
              w_tight,
              thickness + 2 * cut_extra]);
}
