thickness      = 4;     // specimen thickness (Z)
total_length   = 140;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 10;    // transition section length (X)
eps            = 0.5;   // cutter overshoot past faces

$fn = 64;

// ---------- Derived ----------
head_start = -total_length / 2 + grip_length;        // first grip begins
g1         = head_start + grip_length;               // gauge begins
g2         = g1 + gauge_length;                      // gauge ends
t_start    = g2 + transition_len;                    // second grip begins

// ---------- Model ----------
difference() {
    // Outer shape: two grip blocks + gauge + linear transitions
    union() {
        // Left grip
        translate([head_start, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge
        translate([g1, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([t_start, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (s = [-1, 1]) {
            x0 = s > 0 ? g1 : g2;
            x1 = s > 0 ? g2 : g1;
            w0 = grip_width;
            w1 = gauge_width;
            translate([x0, -w0 / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -w0 / 2],
                            [-transition_len, w0 / 2],
                            [x1 - x0, w1 / 2],
                            [x1 - x0, -w1 / 2]]);
        }
    }

    // Central through-cut (keeps the part solid but checks the gauge area)
    translate([g1 - eps, -gauge_width / 2, 0])
        cube([gauge_length + 2 * eps, gauge_width, thickness]);
}
