// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 3;     // specimen thickness (Z)
total_length   = 150;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 50;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 35;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
grip_area     = grip_width * thickness;
gauge_area    = gauge_width * thickness;
transition_dX = (grip_width - gauge_width) / 2;  // width change per transition end

// ---------- Model ----------
difference() {
    union() {
        // Grip sections
        translate([-total_length / 2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        translate([total_length / 2 - grip_length, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([-gauge_length / 2, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition sections (width changes linearly)
        for (s = [-1, 1]) {
            x0 = s > 0 ? total_length / 2 - grip_length : -total_length / 2;
            translate([x0, -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -transition_dX * s],
                             [-transition_len, transition_dX * s],
                             [0, transition_dX * s],
                             [0, -transition_dX * s]]);
        }
    }

    // Cut a small channel along X to avoid coplanar faces at the gauge
    translate([-total_length / 2 - 1, 0, thickness * 0.5])
        cube([total_length + 2, gauge_width + 4, 1]);
}
