// Spoked wheel for small sample cart
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
outer_d      = 80;    // outer rim diameter
rim_w        = 5;     // rim width (radial)
spoke_count  = 8;     // number of spokes
spoke_w      = 5;     // spoke width
hub_d        = 16;    // hub diameter
axle_d       = 5;     // central axle hole diameter
thickness    = 5;     // part thickness (Z)
eps          = 0.5;   // cutter overshoot past faces

$fn = 128;

// ---------- Model ----------
difference() {
    // Outer disc
    cylinder(d = outer_d, h = thickness);

    // Rim cut, leaving a 5 mm wide ring
    translate([0, 0, -eps])
        cylinder(d = outer_d - 2 * rim_w, h = thickness + 2 * eps);

    // Spokes, first along +X axis
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, i * 360 / spoke_count])
            translate([0, -spoke_w / 2, 0])
                cube([outer_d / 2, spoke_w, thickness]);
    }

    // Hub
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = thickness + 2 * eps);

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
