// Powder measuring scoop - hollow spherical bowl with flat handle
// Print orientation: bowl bottom on bed (z = 0), handle extending along +X

// ---------- Parameters ----------
bowl_outer_radius   = 12;   // outer radius of spherical bowl
wall_thickness      = 2;    // thickness of bowl wall
bowl_centre         = [0, 0, 12]; // centre of full sphere
handle_width        = 10;   // handle width along Y
handle_thickness    = 4;    // handle thickness along Z
handle_start_x      = 10;   // handle start position along X
handle_end_x        = 112;  // handle end position along X
cut_extra           = 0.5;  // overshoot for clean boolean cuts
$fn                 = 96;   // curve resolution

// Derived
bowl_inner_radius = bowl_outer_radius - wall_thickness;
handle_top_z      = bowl_centre[2] - wall_thickness; // flush with rim (z = 8..12)

// ---------- Model ----------
union() {
    // Hollow bowl: lower half of spherical shell
    difference() {
        translate(bowl_centre)
            sphere(r = bowl_outer_radius);
        translate(bowl_centre)
            sphere(r = bowl_inner_radius, $fn = $fn);
        // Keep only lower half (z <= bowl_centre[2])
        translate([ -bowl_outer_radius - 1, -bowl_outer_radius - 1, 0 ])
            cube([ 2 * bowl_outer_radius + 2, 2 * bowl_outer_radius + 2, bowl_centre[2] ]);
    }

    // Flat handle, top face flush with rim
    translate([ handle_start_x, -handle_width / 2, handle_top_z ])
        cube([ handle_end_x - handle_start_x, handle_width, handle_thickness ]);
}
