// Ring weight for flask in water bath - a flat torus lying on the bed
// Print orientation: flat on z = 0, middle plane at z = 6

// ---- Dimensions (mm) ----
cross_section_d      = 12;   // diameter of the round cross-section
ring_radius          = 28;   // radius of the circle the cross-section centre follows
outer_diameter       = 68;   // overall diameter of the ring (2*ring_radius + cross_section_d)
height               = 6;    // thickness of the torus (z = 0 to z = 6)

// ---- Modelling parameters ----
eps                  = 0.5;  // cutter overshoot past faces
$fn                  = 128;  // curve resolution

// ---- Model ----
difference() {
    // Solid cylinder along Z, centred on the ring's axis
    translate([0, 0, 0])
        cylinder(h = height + 2 * eps, r = ring_radius + cross_section_d / 2);

    // Through-bore: a cylinder along Z whose axis lies in the XY plane
    // at the inner edge of the ring, running below and above the part
    translate([0, 0, -eps])
        rotate([0, 90, 0])
            cylinder(h = height + 2 * eps, r = cross_section_d / 2);
}
