// Pin hinge leaf
// Print orientation: flat on bed, knuckles above (z = 3..9)

$fn = 64;

// ---- Plate ----
plate_len   = 50;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle diameter (cylinder along X)
knuckle_y   = 10;   // knuckle axis Y position
knuckle_z   = 3;    // knuckle axis Z position
knuckle_n   = 5;    // number of segments along X
knuckle_pitch = plate_len / knuckle_n; // 10 mm segment length
knuckle_h   = 6;    // knuckle height above bed (z = 3 to 9)

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past faces for clean cuts

// Knuckle X positions: 1st, 3rd, 5th segments (indices 0, 2, 4)
function knuckle_x(i) = (i % 2) * knuckle_pitch;

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on +Y edge
        for (i = [0 : knuckle_n - 1])
            if (i % 2 == 0)
                translate([knuckle_x(i), knuckle_y, knuckle_z])
                    cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
    }

    // Pin holes along X axis through every knuckle
    for (i = [0 : knuckle_n - 1])
        if (i % 2 == 0)
            translate([knuckle_x(i), knuckle_y, knuckle_z])
                rotate([0, 90, 0])
                    cylinder(d = pin_d, h = knuckle_h + 2*eps, center = true);
}
