// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

$fn = 64;

// --- Dimensions (mm) ---
thickness      = 3;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 40;    // gauge section length along X
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length along X
transition_len  = 10;    // transition section length between grip and gauge

// Derived
grip_x0        = -total_length/2 + grip_length + transition_len;  // left grip start X
gauge_x0       = grip_x0 + grip_length;                           // gauge start X
right_x0       = gauge_x0 + gauge_length;                         // right grip start X

module specimen() {
    difference() {
        // Outer shape: grip -> transition -> gauge -> transition -> grip
        union() {
            // Left grip
            translate([grip_x0, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
            // Right grip
            translate([right_x0, -grip_width/2, 0])
                cube([grip_length, grip_width, thickness]);
            // Gauge
            translate([gauge_x0, -gauge_width/2, 0])
                cube([gauge_length, gauge_width, thickness]);
            // Transitions (width changes linearly from grip to gauge)
            for (s = [-1, 1]) {
                x0 = s < 0 ? grip_x0 : right_x0;
                w0 = grip_width;
                w1 = gauge_width;
                translate([x0, -w0/2, 0])
                    linear_extrude(thickness)
                        polygon([[-transition_len, -w0/2], [-transition_len, w0/2],
                                 [0, -w1/2], [0, w1/2]]);
            }
        }
        // Central cutout (keeps the part flat on the bed)
        translate([gauge_x0 + (gauge_length - transition_len*2)/2, 0, -1])
            cube([transition_len*2, gauge_width + 4, thickness + 2]);
    }
}

specimen();
