// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 45;    // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 2.5;   // plate thickness along Z

knuckle_d   = 8;     // knuckle (cylinder) diameter
knuckle_z   = 4;     // knuckle axis height above bed
knuckle_n   = 3;     // number of knuckles
knuckle_w   = 15;    // length of each knuckle segment along X
knuckle_hole = 3;    // pin hole diameter

eps         = 0.5;   // cutter overshoot past faces
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles along +Y edge, 1st and 3rd segments only
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 1) continue;   // skip 2nd segment
            translate([-knuckle_w/2 + i * knuckle_w,
                       plate_wid/2 - knuckle_w/2 + i * knuckle_w,
                       knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_w, $fn = $fn);
        }
    }

    // Pin holes along the knuckle axis (through every knuckle)
    for (i = [0 : knuckle_n - 1]) {
        translate([-knuckle_w/2 + i * knuckle_w,
                   plate_wid/2 - knuckle_w/2 + i * knuckle_w,
                   knuckle_z - eps])
            cylinder(d = knuckle_hole, h = knuckle_w + 2 * eps, $fn = $fn);
    }
}
