// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

$fn = 64;

// ---- Plate ----
plate_len   = 45;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 8;    // knuckle diameter (cylinder along X)
knuckle_y   = 15;   // knuckle axis Y position
knuckle_z   = 4;    // knuckle axis Z position
knuckle_n   = 3;    // number of knuckles, equally spaced along X
knuckle_pitch = (plate_len - 2 * knuckle_d/2) / (knuckle_n - 1); // 15 mm

// ---- Pin hole ----
pin_d       = 3;    // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past cut faces

module knuckle(start_x) {
    difference() {
        translate([start_x, knuckle_y, knuckle_z])
            cylinder(d = knuckle_d, h = plate_len, $fn = 96);
        // pin hole along X through the knuckle
        translate([start_x - eps, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = plate_len + 2 * eps, $fn = 64);
    }
}

union() {
    // Plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on the +Y edge, 1st and 3rd segments
    for (i = [0, knuckle_n - 1])
        knuckle(i * knuckle_pitch);
}
