// Pin hinge leaf
// Print orientation: flat on bed, knuckles above (z = 3)

$fn = 64;

// ---- Plate ----
plate_len   = 40;   // plate length along X
plate_wid   = 30;   // plate width along Y
plate_thk   = 2.5;  // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 6;    // knuckle diameter
knuckle_y   = 15;   // knuckle axis Y position
knuckle_z   = 3;    // knuckle axis height (Z)
knuckle_n   = 5;    // number of segments along X
knuckle_pitch = plate_len / knuckle_n; // 8 mm segment length
knuckle_h   = plate_thk + 2 * (knuckle_z - plate_thk / 2); // cylinder height through plate

// ---- Pin ----
pin_d       = 3;    // pin hole diameter

// ---- Cutting overlap ----
eps         = 0.5;  // extension past faces for clean differences

// X positions of segment centres (1st, 3rd, 5th used)
function centre(i) = (i - (knuckle_n + 1) / 2) * knuckle_pitch;

difference() {
    union() {
        // Plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders on odd segments
        for (i = [1 : knuckle_n : knuckle_n * 2 - 1])
            translate([centre(i), knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h, $fn = 96);
    }

    // Pin holes along X through every knuckle
