knuckle_step = plate_len / knuckle_n; // segment length (10 mm)

pin_d       = 2;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len/2, -plate_wid/2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on 1st, 3rd, 5th segments
        for (i = [0 : knuckle_n - 1]) {
            if (i % 2 == 0) { // 0, 2, 4 -> 1st, 3rd, 5th segments
                translate([-knuckle_step * knuckle_n/2 + i * knuckle_step,
                           knuckle_y,
                           knuckle_z])
                    cylinder(d = knuckle_d, h = plate_thk + 2 * eps, $fn = $fn);
            }
        }
    }

    // Pin holes along the knuckle axis through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        if (i % 2 == 0) {
            translate([-knuckle_step * knuckle_n/2 + i * knuckle_step,
                       knuckle_y,
                       knuckle_z - eps])
                cylinder(d = pin_d, h = plate_thk + 2 * eps, $fn = $fn);
        }
    }
}
