// Tapered riser block for beaker setting
// Print orientation: base on bed (z = 0), top face at z = 30

// ---------- Parameters ----------
base_size      = 100;   // bottom square side length (mm)
top_size       = 80;    // top square side length (mm)
height         = 30;    // block height (mm)
pocket_size    = 72;    // square pocket side length (mm)
pocket_depth   = 5;     // square pocket depth from top face (mm)
eps            = 0.5;   // overshoot for clean boolean cuts (mm)
$fn            = 64;    // curve resolution (no curved shapes, set per rules)

// ---------- Derived ----------
// Check: area reduction from base to top is 20%, under the 25% limit.
base_area = base_size * base_size;   // 10000 mm2
top_area  = top_size * top_size;     // 6400 mm2

// ---------- Model ----------
difference() {
    // Main frustum body, centred in X/Y, resting on z = 0
    linear_extrude(height)
        polygon([[-base_size/2, -base_size/2],
                 [ base_size/2, -base_size/2],
                 [ base_size/2,  base_size/2],
                 [-base_size/2,  base_size/2]]);

