            x1 = s < 0 ? -total_length/2 + grip_length : x_mid;
            x2 = s < 0 ? gauge_x0 : x_mid + transition_len;
            w1 = grip_width;
            w2 = gauge_width;
            translate([x1, -w1/2, 0])
                linear_extrude([x2 - x1])
                    polygon([[-w1/2, w1/2], [w1/2, w1/2], [w2/2, w2/2], [-w2/2, -w2/2]]);
        }
    }

    // Cutters, extended past end faces
    translate([-total_length/2 - cut_extra, -gauge_width/2 - cut_extra, 0])
        cube([total_length + 2*cut_extra, gauge_width + 2*cut_extra, thickness + cut_extra]);

    translate([x_mid - cut_extra, -gauge_width/2 - cut_extra, 0])
        cube([total_length + 2*cut_extra, gauge_width + 2*cut_extra, thickness + cut_extra]);
