// Ring weight for flask in water bath - a flat torus lying on the bed
// Print orientation: flat on z = 0, builds upward (+Z), centred on origin in X/Y

// ---------------- Parameters ----------------
ring_d      = 12;    // torus cross-section diameter (minor radius * 2)
ring_r      = 20;    // torus revolution radius (distance of cross-section centre from Z axis)
ring_h      = 6;     // torus middle plane height (z of the centreline of the cross-section)
eps         = 0.5;   // cutter overshoot past faces to avoid coplanar surfaces
$fn         = 128;   // curve resolution

// Derived
minor_r = ring_d / 2;   // minor radius (cross-section radius)
major_r = ring_r;       // major radius (revolution radius)
outer_d = major_r + minor_r;  // ring outer diameter (52 mm)
inner_d = major_r - minor_r;  // ring inner diameter (28 mm)

// ---------------- Model ----------------
difference() {
    // Solid cylinder along Z, centred on the torus centreline
    translate([0, 0, ring_h - minor_r])
        cylinder(h = ring_h * 2, r = minor_r, $fn = $fn);

    // Through-bore: a cylinder along Z, axis on the Z axis at z = ring_h
    translate([0, 0, ring_h - eps])
        cylinder(h = ring_h * 2 + 2 * eps, r = inner_d / 2, $fn = $fn);
}
