            cube([plate_len, plate_wid, plate_thk]);

        // Knuckle cylinders along X
        for (i = knuckle_r)
            translate([-segment_w/2 + i*segment_w, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = plate_len + 2*eps, center = true);
    }

    // Pin holes along X through every knuckle
    for (i = knuckle_r)
        translate([-segment_w/2 + i*segment_w, knuckle_y, knuckle_z])
            translate([-plate_len/2 - eps, 0, -eps])
                cylinder(d = pin_d, h = plate_len + 2*eps);
