    translate([0, 0, -eps])
        cylinder(d = outer_d - 2 * rim_w, h = thickness + 2 * eps);

    // Spokes, first along +X axis
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([0, -spoke_w / 2, -eps])
                cube([spoke_w, spoke_w, thickness + 2 * eps]);

    // Hub
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = thickness + 2 * eps);

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = thickness + 2 * eps);
}
