plate_z1 = plate_thk;
rib_z0   = plate_z1;
rib_z1   = rib_z0 + rib_h;
x_start  = -plate_len/2 + outer_dist - rib_thk/2;   // first rib left edge
x_end    = plate_len/2 - outer_dist - rib_thk/2;    // last rib right edge

// ---------- Model ----------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, evenly spaced across the allowed X range
    for (i = [0 : rib_count - 1]) {
