$fn            = 64;    // curve resolution (no curves here, set per rules)

// ---------------- Derived ----------------
rib_x0 = -plate_len/2 + rib_outer_dist;   // first rib centre X
// check: last rib centre = rib_x0 + (rib_count-1)*rib_pitch
// = -60 + 3*24 = 12 ; outer distance = 120/2 - 12 = 48 ? 
// The given numbers do not sum to the plate length.
// Enforce the first rib position and the pitch, and let the last
// rib run off the end (or add a small overlap) so the model is
// self-consistent. The user may adjust rib_outer_dist if they want
// the last rib exactly at the other end.

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs
    for (i = [0 : rib_count - 1]) {
        translate([rib_x0 + i * rib_pitch - rib_thk/2,
                   -rib_thk/2,
                   plate_thk])
            cube([rib_thk, rib_thk, rib_h]);   // square rib in X/Y
    }
}
