// Pin hinge leaf
// Print orientation: flat on bed, knuckles pointing up (+Z)

// ---------- Parameters ----------
plate_len   = 45;    // plate length along X (mm)
plate_wid   = 25;    // plate width along Y (mm)
plate_thk   = 2.5;   // plate thickness along Z (mm)

knuckle_d   = 7;     // knuckle cylinder diameter (mm)
knuckle_z   = 3.5;   // knuckle axis height above bed (mm)
knuckle_y   = 12.5;  // knuckle axis Y position (mm)
knuckle_h   = 15;    // knuckle arc height from plate top (mm)
knuckle_n   = 3;     // number of knuckles
knuckle_f   = [0, 2]; // knuckle indices that sit on the plate (0-based)

pin_d       = 3;     // pin hole diameter (mm)

eps         = 0.5;   // cutter overshoot past faces (mm)
$fn         = 96;    // curve resolution

// ---------- Derived ----------
seg   = plate_len / knuckle_n;        // segment length (15 mm)
r     = knuckle_d / 2;
top_z = plate_thk + knuckle_h;        // top of knuckle arc

// ---------- Model ----------
difference() {
    union() {
        // Base plate, centred in X/Y, resting on z = 0
        translate([-plate_len / 2, -plate_wid / 2, 0])
            cube([plate_len, plate_wid, plate_thk]);

        // Knuckles on the +Y edge, on the specified segments
        for (i = knuckle_f)
            translate([i * seg - seg / 2, knuckle_y, knuckle_z])
                cylinder(d = knuckle_d, h = knuckle_h, $fn = $fn);
    }

    // Pin hole along the knuckle axis through every knuckle
    for (i = [0 : knuckle_n - 1])
        translate([i * seg - seg / 2, knuckle_y, knuckle_z])
            cylinder(d = pin_d, h = knuckle_h + eps, $fn = $fn);
}
