gauge_x0   = head_start + grip_length + transition_len;  // gauge starts
head_end   = total_length / 2 - grip_length;          // last grip ends

// ---------- Width profile ----------
function w(x) =
    x < head_start || x > head_end     ? grip_width
    : x < gauge_x0                     ? grip_width + (gauge_width - grip_width) * (x - head_start) / transition_len
    : x > gauge_x0 + gauge_length      ? grip_width + (gauge_width - grip_width) * (head_end - x) / transition_len
    : gauge_width;

