// Flat tensile test specimen (dog bone) for printed plastic
// Print orientation: flat on bed, z = 0 to thickness

// ---------- Parameters ----------
thickness      = 4;     // specimen thickness (Z)
total_length   = 110;   // overall length along X
gauge_width    = 8;     // narrow gauge section width (Y)
gauge_length   = 30;    // gauge section length (X)
grip_width     = 19;    // grip section width (Y)
grip_length    = 25;    // grip section length (X)
transition_len = 15;    // transition section length (X)

// Derived
grip_count     = 2;     // number of grip sections
cut_extra      = 0.5;   // overshoot for clean cuts

$fn = 64;

// ---------- Model ----------
difference() {
    // Solid block
    translate([-total_length/2, -thickness/2, 0])
        cube([total_length, thickness, thickness]);

    // Grip cutouts, centred at each end
    for (i = [0 : grip_count - 1]) {
        x0 = (i == 0) ? -total_length/2 + grip_length :
              total_length/2 - grip_length;
        translate([x0 - cut_extra, -grip_width/2, -cut_extra])
            cube([grip_length + 2*cut_extra, grip_width, 2*cut_extra]);
    }

    // Gauge cutout, centred
    translate([-gauge_length/2, -gauge_width/2, -cut_extra])
        cube([gauge_length, gauge_width, 2*cut_extra]);

    // Transition cutouts, width changes linearly from grip to gauge
    for (i = [0 : grip_count - 1]) {
        x0 = (i == 0) ? -total_length/2 + grip_length + transition_len :
              total_length/2 - grip_length - transition_len;
        w1 = grip_width;
        w2 = gauge_width + (grip_width - gauge_width) * transition_len / transition_len;
        translate([x0 - cut_extra, -w1/2, -cut_extra])
            cube([transition_len, w1, 2*cut_extra]);
    }
}
