        for (s = [-1, 1])
            translate([s > 0 ? grip_x0 : gauge_x0 - grip_length, -grip_width / 2, 0])
                cube([grip_length, grip_width, thickness]);

        // Gauge section
        translate([gauge_x0, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Transition sections (width changes linearly from 15 to 8 mm)
        for (s = [-1, 1])
            translate([s > 0 ? gauge_x0 - transition_len : grip_x0 - transition_len,
                       -grip_width / 2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, 0], [0, grip_width], [0, -grip_width],
                            [-transition_len, 0]]);
    }

    // Cut a central notch along X to reduce stress concentration
    translate([0, -gauge_width / 2 - 1, 0])
        cube([total_length, gauge_width + 2, thickness]);
