axle_d       = 5;     // central axle hole diameter
t            = 5;     // part thickness (Z)
eps          = 0.5;   // cutter overshoot past faces

$fn = 96;

// ---------- Model ----------
difference() {
    // Outer disc
    cylinder(d = outer_d, h = t);

    // Rim cut, leaving a 4 mm wide ring
    translate([0, 0, -eps])
        cylinder(d = outer_d - 2 * rim_w, h = t + 2 * eps);

    // Spokes, first along +X axis
    for (i = [0 : spoke_count - 1])
        rotate([0, 0, i * 360 / spoke_count])
            translate([0, -spoke_w / 2, 0])
                cube([spoke_w, spoke_w, t]);

    // Hub
    translate([0, 0, -eps])
        cylinder(d = hub_d, h = t + 2 * eps);

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = t + 2 * eps, $fn = 64);
}
