// Spoked wheel for small sample cart - flat part, printed lying on the bed
// Print orientation: flat on bed, z = 0 to part_t

// ---------- Parameters ----------
outer_d      = 100;   // outer rim diameter
rim_w        = 5;     // rim width (radial)
spoke_count  = 8;     // number of spokes
spoke_w      = 5;     // spoke width (radial)
hub_d        = 14;    // hub diameter
axle_d       = 8;     // central axle hole diameter
part_t       = 5;     // part thickness (Z)

eps          = 0.5;   // cutter overshoot past faces
$fn          = 128;   // curve resolution

// ---------- Model ----------
difference() {
    // Outer disc
    cylinder(d = outer_d, h = part_t);

    // Rim, hub and spoke cutouts (cut from the top face, z = part_t - 1)
    for (i = [0 : spoke_count - 1]) {
        rotate([0, 0, i * 360 / spoke_count])
            translate([0, 0, part_t - 1])
                union() {
                    // Spoke cutout, running along +X from the hub
                    translate([hub_d / 2 - spoke_w / 2, -spoke_w / 2, 0])
                        cube([spoke_w, spoke_w, part_t - 1]);

                    // Outer rim cutout, a rectangular slot along +X
                    translate([outer_d / 2 - rim_w, -rim_w / 2, 0])
                        cube([rim_w, rim_w, part_t - 1]);
                }
    }

    // Central hub with axle hole
    translate([0, 0, part_t - 1])
        cylinder(d = hub_d, h = part_t - 1);

    // Axle hole through the centre
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = part_t + 2 * eps);
}
