// Stiffened cover panel: flat plate with 3 longitudinal ribs
// Print orientation: plate flat on bed, ribs pointing up (+Z)

// ---------------- Parameters ----------------
plate_len   = 80;   // plate length along X (mm)
plate_wid   = 80;   // plate width along Y (mm)
plate_thk   = 2;    // plate thickness along Z (mm)

rib_thk     = 2;    // rib thickness along X (mm)
rib_h       = 4;    // rib height above plate top (mm)
              // -> rib top at z = plate_thk + rib_h = 6

rib_count   = 3;    // number of ribs
rib_pitch   = 20;   // centre-to-centre spacing of ribs along X (mm)
outer_dist  = 20;   // distance from outer rib centre to plate end (mm)

eps         = 0.5;  // cutter overshoot past faces (mm)
$fn         = 64;   // curve resolution

// ---------------- Derived ----------------
plate_z0 = 0;                 // plate bottom Z
plate_z1 = plate_thk;         // plate top Z
rib_z0   = plate_z1;          // rib bottom Z (on plate top)
rib_z1   = rib_z0 + rib_h;    // rib top Z
x_start  = -plate_len/2 + outer_dist;  // first rib centre X
// check: last rib centre X = x_start + (rib_count-1)*rib_pitch
//                          = -40 + 20 + 2*20 = 20 -> 20 mm from right end

// ---------------- Model ----------------
union() {
    // Flat plate
    translate([0, 0, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs running full width along Y
    for (i = [0 : rib_count - 1]) {
        translate([x_start + i * rib_pitch - rib_thk/2,
                   -plate_wid/2,
                   rib_z0])
            cube([rib_thk, plate_wid, rib_h + eps]);  // overshoot top face
    }
}
