rib_z1   = rib_z0 + rib_h;
x0       = -plate_len/2;
x1       = plate_len/2;

// Check: 4 ribs at pitch 24 with 24 mm end clearances span 120 mm
assert(abs(rib_pitch*(rib_count-1) + 2*rib_outer_dist - plate_len) < 0.001,
       "Rib parameters do not fill the plate length.");

// ---------------- Model ----------------
union() {
    // Base plate
    translate([x0, -plate_wid/2, plate_z0])
        cube([plate_len, plate_wid, plate_thk]);

    // Ribs, evenly spaced across the plate
    for (i = [0 : rib_count - 1]) {
        rib_x = rib_outer_dist + i * rib_pitch;
        translate([rib_x - rib_thk/2, -plate_wid/2, rib_z0])
            cube([rib_thk, plate_wid, rib_h]);
    }
