    // Main block, centred in X/Y, sitting on z = 0
    translate([-block_len/2, -block_wid/2, 0])
        cube([block_len, block_wid, block_ht]);

    // Semicircular tunnels: cylinder axis along Y, centre line along X
    for (i = [0 : tunnel_n - 1]) {
        x_c = (i - (tunnel_n - 1)/2) * tunnel_pitch;
        translate([x_c - tunnel_d/2, -tunnel_d/2, 0])
            rotate([0, 90, 0])
                cylinder(d = tunnel_d, h = block_wid + 2*eps, center = true);
    }
