    translate([0, 0, 0])
        cylinder(r = ring_radius, h = cross_section_d, $fn = 256);

    // Central bore: a through-hole of inner_diameter, split along z so the cut
    // overshoots both the top and bottom faces by cut_extra
    translate([0, 0, -cut_extra])
        union() {
            cylinder(r = inner_diameter / 2, h = height / 2 + cut_extra + 0.01, $fn = 256);
            translate([0, 0, height / 2 - (height / 2 + cut_extra + 0.01)])
                cylinder(r = inner_diameter / 2, h = height / 2 + cut_extra + 0.01, $fn = 256);
        }
