// Pin hinge leaf
// Print orientation: flat on bed, knuckles above (z = 3.5 .. 10.5)

$fn = 64;

// ---- Plate ----
plate_len   = 40;   // plate length along X
plate_wid   = 20;   // plate width along Y
plate_thk   = 3;    // plate thickness along Z

// ---- Knuckles ----
knuckle_d   = 7;    // knuckle diameter
knuckle_z   = 3.5;  // knuckle axis height (z)
knuckle_n   = 5;    // number of segments along X
knuckle_pitch = plate_len / knuckle_n; // 8 mm segment length
knuckle_xs = [i * knuckle_pitch for i in [0, 2, 4]]; // 1st, 3rd, 5th segments

// ---- Pin hole ----
pin_d = 3;          // pin hole diameter

// ---- Cutting overlap ----
eps = 0.5;          // extension past faces to avoid coplanar surfaces

module knuckle(xc) {
    // cylinder axis along X, centred at y = plate_wid/2, z = knuckle_z
    difference() {
        translate([xc - knuckle_d/2, plate_wid/2, knuckle_z])
            cylinder(d = knuckle_d, h = plate_len + 2*eps, $fn = 96);
        // pin hole along X through the knuckle
        translate([xc - knuckle_d/2 - eps, plate_wid/2, knuckle_z])
            cylinder(d = pin_d, h = plate_len + 2*eps + pin_d + 2*eps, $fn = 96);
    }
}

union() {
    // Plate, centred in X and Y, resting on z = 0
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Knuckles on the +Y edge
    for (xc in knuckle_xs)
        knuckle(xc);
}
