    // Pin holes through every knuckle
    for (i = [0 : knuckle_n - 1]) {
        x = (i - (knuckle_n - 1)/2) * knuckle_pitch;
        translate([x, knuckle_z - eps, knuckle_z + eps])
            cylinder(d = pin_d, h = plate_thk + 2*eps);
    }
}
