    for (i = [0 : n_points - 1]) {
        a = i * 360 / n_points;
        r = (i % 2 == 0) ? outer_r : inner_r;
        translate([r * cos(a), r * sin(a), 0])
            cylinder(h = thickness, r = 1);   // radius = 1: thin spine
