g2         = t2 + transition_len;                    // second grip begins
tail_end   = g2 + grip_length;                       // last grip ends

// ---------- Model ----------
difference() {
    // Outer shape: two grip blocks + two transition blocks + gauge block
    union() {
        // Left grip
        translate([head_start, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Right grip
        translate([g2, -grip_width / 2, 0])
            cube([grip_length, grip_width, thickness]);

        // Left transition (width: grip_width -> gauge_width)
        translate([head_start, -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon([[-grip_length / 2, -grip_width / 2],
                         [-grip_length / 2,  grip_width / 2],
                         [transition_len - gauge_length / 2, gauge_width / 2],
                         [transition_len - gauge_length / 2, -gauge_width / 2]]);

        // Right transition (width: gauge_width -> grip_width)
        translate([t2, -grip_width / 2, 0])
            linear_extrude(thickness)
                polygon([[transition_len - gauge_length / 2, -gauge_width / 2],
                         [transition_len - gauge_length / 2,  gauge_width / 2],
                         [grip_length / 2,  grip_width / 2],
                         [grip_length / 2,  -grip_width / 2]]);

        // Gauge section
        translate([g1, -gauge_width / 2, 0])
            cube([gauge_length, gauge_width, thickness]);
    }

    // Through-thickness cutters, extended past top and bottom faces
    translate([-total_length / 2 - eps, -gauge_width / 2 - eps, -eps])
        cube([total_length, gauge_width + 2 * eps, thickness + 2 * eps]);

    translate([-total_length / 2 - eps, 0, -eps])
        cube([total_length, eps, thickness + 2 * eps]);

    translate([-total_length / 2 - eps, gauge_width + eps, -eps])
        cube([total_length, eps, thickness + 2 * eps]);
