// Spoked wheel for small sample cart - flat part, printed lying on the bed
// Print orientation: flat on bed, z = 0 to part_t

// ---------- Parameters ----------
part_t      = 6;     // part thickness (Z)
outer_d     = 100;   // outer rim diameter
rim_w       = 6;     // rim width (radial)
hub_d       = 20;    // hub diameter
axle_d      = 8;     // central axle hole diameter
spoke_d     = 4;     // spoke width
spoke_n     = 6;     // number of spokes
first_spoke = 0;     // first spoke angle (deg), 0 = +X axis

eps         = 0.5;   // cutter overshoot past faces
$fn         = 128;   // curve resolution

// ---------- Derived ----------
rim_i = outer_d - 2 * rim_w;   // inner diameter of rim (ring width)
r     = outer_d / 2;           // outer radius

// ---------- Model ----------
difference() {
    union() {
        // Outer rim (ring)
        cylinder(d = outer_d, h = part_t);

        // Central hub
        cylinder(d = hub_d, h = part_t);

        // Spokes, evenly spaced, first along +X
        for (i = [0 : spoke_n - 1]) {
            a = first_spoke + i * 360 / spoke_n;
            translate([r * cos(a), r * sin(a), 0])
                cube([spoke_d, r, part_t]);
        }
    }

    // Axle hole through the hub
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = part_t + 2 * eps);
}
```

