// Eccentric cam for shaker mechanism
// Print orientation: disc flat on bed, hub rising above (z = 0 to 11)

// ---------- Parameters ----------
cam_d        = 30;    // cam disc diameter
cam_t        = 5;     // cam disc thickness
cam_x        = 4;     // cam disc centre X offset (y = 0)
shaft_d      = 12;    // shaft hub diameter
shaft_h      = 6;     // shaft hub height above disc (z = 5 to 11)
shaft_bore   = 6;     // central shaft hole diameter
eps          = 0.5;   // cutter overshoot past faces
$fn          = 96;    // curve resolution

// ---------- Model ----------
union() {
    // Cam disc
    translate([cam_x, 0, 0])
        cylinder(d = cam_d, h = cam_t);

    // Shaft hub (overlaps disc; union fuses them)
    translate([cam_x, 0, cam_t])
        cylinder(d = shaft_d, h = shaft_h);

    // Central bore through hub and disc
    translate([cam_x, 0, -eps])
        cylinder(d = shaft_bore, h = cam_t + shaft_h + 2 * eps);
}
