// Star-shaped indexing wheel - flat plate with central hole
// Print orientation: flat on bed, z = 0 upward

// ---------- Parameters ----------
outer_r   = 40;   // distance from centre to outer points
inner_r   = 24;   // distance from centre to inner points
thickness = 5;    // plate thickness (Z)
hole_d    = 8;    // central through-hole diameter
eps       = 0.5;  // cutter overshoot past faces

n_points  = 8;    // number of star points (even)

$fn = 96;

// ---------- Model ----------
difference() {
    // Outline: alternating outer/inner points, first outer on +X axis
    for (i = [0 : n_points - 1]) {
        r = (i % 2 == 0) ? outer_r : inner_r;
        a = i * 360 / n_points;
        hull() {
            translate([r * cos(a), r * sin(a), 0])
                cylinder(h = thickness, r = 1);
            translate([r * cos(a + 180 / n_points),
                       r * sin(a + 180 / n_points), 0])
                cylinder(h = thickness, r = 1);
        }
    }

    // Central through-hole
    translate([0, 0, -eps])
        cylinder(h = thickness + 2 * eps, d = hole_d);
}
