    // Frustum body, built from a bottom square up to the top square
    linear_extrude(height)
        polygon([[-bottom_size / 2, -bottom_size / 2],
                [bottom_size / 2, -bottom_size / 2],
                [bottom_size / 2, bottom_size / 2],
                [-bottom_size / 2, bottom_size / 2]]);

    // Square pocket cut into the top face, extended above the face to avoid coplanar faces
    translate([0, 0, height - pocket_depth])
        cube([pocket_size, pocket_size, pocket_depth + eps]);
