difference() {
    // Outer shape
    translate([-total_length / 2, -width_func(x_mid) / 2, 0])
        linear_extrude(thickness)
            polygon([for (x = [-total_length / 2 : total_length / 100])
                       [x, width_func(x) / 2]]);

    // Central cut to reduce mass / improve grip
    translate([-x_mid + gauge_length / 2, -gauge_width / 2, -1])
        cube([gauge_length, gauge_width, thickness + 2]);
}

// Width at position x, used above and below
function width_func(x) {
    if (x < transition_len)
        return grip_width;
    else if (x < transition_len + gauge_length)
        return gauge_width + (grip_width - gauge_width) *
               (x - transition_len) / transition_len;
    else if (x < transition_len + gauge_length + transition_len)
        return grip_width;
    else
        return grip_width;
}
