    union() {
        // Outer rim ring
        cylinder(d = outer_d, h = part_t);

        // Hub
        cylinder(d = hub_d, h = part_t);

        // Spokes, evenly spaced
        for (i = [0 : spoke_count - 1]) {
            a = first_angle + i * 360 / spoke_count;
            translate([spoke_len * cos(a), spoke_len * sin(a), 0])
                cube([spoke_w, spoke_w, part_t]);
        }
    }

    // Through holes
    translate([0, 0, -eps])
        cylinder(d = axle_d, h = part_t + 2 * eps);
