// T-shaped extrusion nut - slides into the slot of an aluminium profile.
// Print orientation: flange on the bed (z = 0), neck pointing up.
//
// NOTE: This is a solid parts file, not a model that generates a lattice
// or any internal honeycomb structure. It has no horizontal layers at z = 3
// and no patterned cutouts - just the two solid blocks and the screw hole.
//
// Parameters (mm):
//   flange_w   - flange width (Y)
//   flange_t   - flange thickness (z = 0 to 2)
//   neck_w     - neck width (Y), centred on the flange
//   neck_h     - neck height above the flange (z = 2 to 8)
//   length     - part length along X
//   screw_d    - central screw hole diameter
//   eps        - cutter overshoot past faces

$fn = 64;

flange_w   = 12;
flange_t   = 2;
neck_w     = 8;
neck_h     = 6;
length     = 20;
screw_d    = 3.4;
eps        = 0.5;

difference() {
    union() {
        // Bottom flange: full width, centred in X and Y
        translate([-length / 2, -flange_w / 2, 0])
            cube([length, flange_w, flange_t]);

        // Neck: centred on the flange in X and Y, rising above it
        translate([-neck_w / 2, -neck_w / 2, flange_t])
            cube([neck_w, neck_w, neck_h]);
    }

    // Central vertical screw hole, through the entire part
    translate([0, 0, -eps])
        cylinder(d = screw_d, h = flange_t + neck_h + 2 * eps);
}
