                x1 = side < 0 ? gauge_start_x : gauge_start_x + transition_len;
                w0 = grip_width;
                w1 = gauge_width;
                translate([x0, -w0/2, 0])
                    linear_extrude(thickness)
                        polygon([x0, x1], [w0, w1]);
