        translate([gauge_start_x, -gauge_width/2, 0])
            cube([gauge_length, gauge_width, thickness]);

        // Right grip
        translate([grip_end_x - grip_length, -grip_width/2, 0])
            cube([grip_length, grip_width, thickness]);

        // Transitions (width changes linearly from grip to gauge)
        for (side = [-1, 1]) {
            x0 = side < 0 ? grip_start_x : gauge_end_x;
            x1 = x0 + transition_len;
            w0 = grip_width;
            w1 = gauge_width + side * (grip_width - gauge_width);
            translate([x0, -w0/2, 0])
                linear_extrude(thickness)
                    polygon([[-transition_len, -w0/2],
                             [-transition_len, w0/2],
                             [0, w1/2],
                             [0, -w1/2]]);
        }
    }

    // Cut a small notch along the centreline to avoid coplanar faces
    translate([0, 0, thickness - 0.01])
        cube([total_length, 2, 0.01]);
}
